from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Scfc_value_to_ui(EmssimCommand):
    def __init__(self, method="scfc_value_to_ui", timeout=60, rpc_connection_name='localRPC'):
        super(Scfc_value_to_ui, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Scfc_value_to_ui, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "User Interface value"):
                for attribute, value in data["value"].items():
                    self._ret[attribute] = str(value)
        elif ("status" in data):
            self._ret["status"] = data["status"]
